#include <iostream>
#include <string>
using namespace std;

class Account {
protected:
    string id;
    int balance;
public:
    Account(string i, int b) : id(i), balance(b) {}

    void save(int amount) {
        balance = balance + amount;
        cout << id << " 存进 " << amount << " 条，现在 " << balance << " 条" << endl;
    }
};

class SavingsAccount : public Account {
protected:
    int rate;
public:
    SavingsAccount(string i, int b, int r) : Account(i, b), rate(r) {}

    int interest() {
        return balance * rate / 100;
    }
};

int main() {
    int n = 0;
    cin >> n;

    SavingsAccount s("S1", 60, 10);

    for (int i = 0; i < n; i++) {
        int amount = 0;
        cin >> amount;
        s.save(amount);
    }

    cout << "利息 " << s.interest() << " 条" << endl;
    return 0;
}
